INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at)
VALUES ('a0b389d5-4c1f-4c9e-a07c-b7861665ef81', 'milhas-sem-misterio', 'published', 'dicas-de-viagem', 'Milhas sem mistério: entenda, compare com o dinheiro e confira o saldo', 'sem mistério', 'O básico para entender milhas e pontos, comparar com o preço em dinheiro e conferir o seu saldo com tranquilidade, com fontes oficiais conferidas em 22/10/2026 e o guia em PDF para baixar de graça.', 'Entenda o que são milhas, compare com o preço em dinheiro e confira o seu saldo e a validade, sem pressa e sem promessa de economia.', NULL, NULL, '/assets/blog/milhas-sem-misterio.jpg', '/assets/blog/milhas-sem-misterio-m.jpg', 'Asa de avião ao pôr do sol, com o sol baixo refletido no mar e nuvens abaixo', 0, '[{"t":"pdf","href":"/guias/milhas-sem-misterio.pdf","note":"Versão em PDF para guardar no celular. Grátis, sem cadastro."},{"t":"p","text":"Guia Rota Certa, atualizado em outubro de 2026, com fontes conferidas em 22/10/2026. Ele explica o básico e **não promete economia**: cada caso é um caso."},{"t":"tip","items":["Um número entre colchetes, como [1], marca um fato com fonte oficial, listada em **Fontes**, no fim da página.","**Recomendação:** é um conselho da Rota Certa, não uma regra.","**Não verificado:** é um ponto que não conseguimos confirmar em fonte oficial."],"title":"Como ler este guia"},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Milhas sem mistério e quero cotar uma passagem."},{"t":"h","text":"O que são milhas e pontos"},{"t":"p","text":"Milhas e pontos funcionam como uma moeda de um programa de fidelidade: ficam como saldo na sua conta dentro do programa. O mercado costuma chamar de pontos o saldo de cartões de crédito e de milhas o saldo dos programas das companhias aéreas. [1] Servem para pagar parte de uma passagem ou a passagem inteira, conforme as regras de cada programa."},{"t":"img","src":"/assets/blog/milhas-por-do-sol-na-asa.jpg","alt":"Pôr do sol visto da janela do avião, com asa, motor e horizonte alaranjado","caption":"Milhas e pontos viram saldo na sua conta, dentro de cada programa.","credit":"Foto: Stefan Stefancik / Pexels","w":1000,"h":667},{"t":"p","text":"A Smiles informa que as milhas entram na conta de várias formas, entre elas voos, compra de milhas, transferência de pontos do cartão ou do banco, reativação e parceiros. [2] O que muda de um programa para outro são as regras."},{"t":"h","text":"Por que podem vencer"},{"t":"ul","items":["Milhas têm validade, e o prazo não é igual para todo mundo.","A Smiles informa que o prazo de validade varia conforme a forma como as milhas foram acumuladas. Milhas bônus de promoções e milhas do clube de assinatura aparecem com regras próprias. [2]","Na LATAM Pass, a validade das milhas depende do programa e da categoria do cliente: segundo o blog oficial, clientes de certas categorias Elite ou com cartões específicos podem ter pontos que nunca expiram. Milhas vencidas são removidas da conta e não podem mais ser usadas. [1]","A Smiles tem o serviço Reativar Milhas, para recuperar milhas expiradas, e um serviço no app para estender a validade das milhas. [2]"]},{"t":"img","src":"/assets/blog/milhas-asa-vermelha.jpg","alt":"Asa de avião com ponta vermelha sobre um mar de nuvens, em céu claro","caption":"A regra muda de programa para programa.","credit":"Foto: ArtHouse Studio / Pexels","w":1000,"h":667},{"t":"p","text":"**A regra muda de programa para programa.** **Recomendação:** confira a regra atual no site do seu programa: prazo contado por amigo, grupo ou vídeo pode estar desatualizado."},{"t":"h","text":"Milhas ou dinheiro?"},{"t":"ul","items":["**1.** Veja o **preço total em dinheiro** da passagem, para o mesmo voo, a mesma data e o mesmo tipo de tarifa.","**2.** Veja **quantas milhas** o programa pede e quanto você paga de **taxas em dinheiro**.","**3.** Divida o preço em dinheiro pelas milhas pedidas: esse é o **valor de cada milha**. Para o valor de mil milhas, multiplique por mil.","**4.** Some as taxas pagas em dinheiro. Com milhas, você paga as milhas **mais** essas taxas.","**5.** Compare com o que as suas milhas custaram ou valem para você."]},{"t":"tip","items":["Só para mostrar a conta: preço da passagem em dinheiro 1.200; milhas pedidas 40.000; taxas em dinheiro 150.","1.200 ÷ 40.000 = 0,03 por milha, ou 30 por mil milhas.","Na opção com milhas: 40.000 milhas mais 150 em dinheiro."],"title":"Exemplo com números inventados"},{"t":"p","text":"**Opcional.** **Conta mais justa, se quiser:** tire as taxas do resgate do preço em dinheiro antes de dividir, porque as taxas aparecem nos dois casos. É só aritmética, sem fonte e sem obrigação."},{"t":"img","src":"/assets/blog/milhas-mar-de-nuvens.jpg","alt":"Vista aérea de um mar de nuvens ao entardecer, com céu azul e rosado e ponta de asa no topo","caption":"Compare o mesmo voo, a mesma data e o mesmo tipo de tarifa.","credit":"Foto: Miguel Cuenca / Pexels","w":1000,"h":667},{"t":"h","text":"Saldo e validade"},{"t":"p","text":"**Sempre no site ou app do programa.** Digite o endereço você mesmo e não clique em links recebidos por mensagem."},{"t":"ul","items":["Na Smiles, o quadro Milhas a Expirar fica na parte de cima, à direita, da página da conta. O programa também envia todo mês uma newsletter com o saldo e as milhas perto de expirar. [2]","**Recomendação:** na LATAM Pass, acompanhe o saldo pelo app ou pelo site, para não deixar as milhas vencerem sem perceber.","**Recomendação:** anote quantas milhas você tem, de que tipo são e quando vence cada grupo. Refaça a conferência antes de planejar a viagem."]},{"t":"img","src":"/assets/blog/milhas-notebook-aeroporto.jpg","alt":"Notebook aberto sobre uma mesa de aeroporto, com copo de café e luz dourada ao fundo","caption":"Confira o saldo com calma, direto no site ou no app do programa.","credit":"Foto: K / Pexels","w":1000,"h":667},{"t":"h","text":"Taxa de embarque e outras taxas"},{"t":"ul","items":["A taxa de embarque remunera os serviços, as instalações e os equipamentos usados no despacho, no embarque e no desembarque do passageiro. As companhias a arrecadam antes do embarque e a repassam ao operador do aeroporto (arts. 4 e 19). [3]","A oferta de passagem, em qualquer canal de venda, deve mostrar o valor total a pagar: serviço de transporte aéreo, tarifas aeroportuárias e valores devidos a órgãos do governo (art. 4). [4]","As multas contratuais não podem passar do valor do transporte aéreo, e tarifas aeroportuárias e valores devidos a órgãos do governo ficam fora do cálculo (art. 9). [4]","A companhia tem 7 dias, a contar da sua solicitação, para reembolsar pelo mesmo meio de pagamento da compra. Tarifas aeroportuárias e valores devidos a órgãos do governo são devolvidos integralmente (art. 29). [4]"]},{"t":"p","text":"**Não verificado:** se as Resoluções 400 e 432 da ANAC valem do mesmo jeito para passagens emitidas com milhas. Confira as taxas no seu programa antes de emitir."},{"t":"img","src":"/assets/blog/milhas-saguao-aeroporto.jpg","alt":"Saguão amplo de aeroporto com fileiras de assentos vazios e luz natural entrando pelas janelas","caption":"A taxa de embarque é arrecadada antes do embarque.","credit":"Foto: Tiago Alvar / Pexels","w":1000,"h":667},{"t":"h","text":"Erros comuns de iniciante"},{"t":"ul","items":["Olhar só o número de milhas e esquecer as taxas pagas em dinheiro.","Deixar as milhas vencerem por não conferir a validade.","Confiar num prazo ouvido por aí em vez da página do programa.","Comparar tarifas diferentes. Em geral, tarifas mais baratas têm regras menos flexíveis e multas maiores, e as promocionais podem até não ser reembolsáveis. [5]","Não planejar o custo total. O Procon Paulistano recomenda fazer um planejamento financeiro de toda a viagem. [6]"]},{"t":"h","text":"Antes de usar suas milhas"},{"t":"ul","items":["☐ Anotei o **saldo e a validade** das minhas milhas no site ou app do programa.","☐ Li a **regra atual** do programa para o tipo de milha que tenho.","☐ Comparei com o **preço total em dinheiro** do mesmo voo, data e tarifa.","☐ Somei as **taxas pagas em dinheiro**, incluindo a taxa de embarque.","☐ Conferi **bagagem, remarcação e reembolso** da tarifa antes de emitir."]},{"t":"p","text":"**Sem pressa.** **Recomendação:** não tenha pressa de emitir: compare com calma e confira as regras do programa antes."},{"t":"img","src":"/assets/blog/milhas-aviao-entardecer.jpg","alt":"Avião visto de frente em voo, com faróis acesos e céu alaranjado ao entardecer","caption":"Compare com calma antes de emitir.","credit":"Foto: William Lopez / Pexels","w":1000,"h":667},{"t":"pdf","href":"/guias/milhas-sem-misterio.pdf","note":"Leve o passo a passo e a lista de conferência no celular. Grátis, sem cadastro."},{"t":"h","text":"Não verificado"},{"t":"ul","items":["**Prazos.** Os prazos de validade em número, de qualquer programa, não são citados.","**Valores e promoções.** Valor do milheiro, bônus de transferência ou de compra e promoções.","**Outros programas.** Regras de Azul Fidelidade (página oficial bloqueada em 21/10/2026), TAP Miles&Go e Iberia Club (não consultados).","**LATAM Pass.** Detalhes das regras além do blog oficial citado: outras páginas do programa deram acesso negado em 21/10/2026.","**Taxas na emissão com milhas.** Não conseguimos confirmar, em página oficial aberta hoje, se na emissão com milhas as taxas são pagas em dinheiro, nem em quais programas. **Recomendação:** antes de emitir, veja quanto será cobrado de taxas no seu programa.","**Taxa de embarque.** O valor em cada aeroporto.","**Milhas e a Resolução 400.** Se as Resoluções 400 e 432 da ANAC valem do mesmo jeito para passagens emitidas com milhas.","**Procon.** A posição do Procon sobre vencimento de milhas.","**Câmbio e IOF.** Na parte em dinheiro de passagens internacionais (nenhuma fonte do Banco Central foi usada)."]},{"t":"tip","items":["[1] [LATAM Pass, como evitar que milhas e pontos expirem (blog oficial)](https://web.latampass.latam.com/pt_br/vem-com-milhas/descubra-como-evitar-que-suas-milhas-e-pontos-expirem-e-mantenha-os-sempre-ativos)","[2] [Smiles, validade de milhas](https://www.smiles.com.br/validade-de-milhas)","[3] [ANAC, Resolução 432/2017 (tarifas aeroportuárias), arts. 4 e 19](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2017/resolucao-no-432-13-06-2017)","[4] [ANAC, Resolução 400/2016, texto compilado (versão vigente em 22/10/2026), arts. 4, 9 e 29](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/resolucoes-2016/resolucao-no-400-13-12-2016)","[5] [ANAC, página Oferta e compra da passagem (atualizada em 13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/oferta-e-compra-da-passagem)","[6] [Procon Paulistano (Prefeitura de São Paulo), Cartilha do Transporte Aéreo (arquivo de 2022)](https://prefeitura.sp.gov.br/documents/d/procon/cartilha-transporte-aereo-procon)","[7] [ANAC, Resolução 800/2026 (passageiro indisciplinado; alterou os arts. 5 e 18 da Res. 400)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-800)","[8] [ANAC, Resolução 813/2026 (altera a Res. 400; vale a partir de 26/10/2026)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-813)"],"title":"Fontes, conferidas em 22/10/2026"},{"t":"p","text":"**Versão da norma.** Resolução ANAC 400/2016, texto compilado no site da ANAC (última modificação em 26/08/2026, com as Resoluções 434/2017, 692/2022 e 800/2026 [7]), vigente em 22/10/2026. Os artigos citados são os dessa versão. A Resolução ANAC 813/2026 só vale a partir de 26/10/2026 e altera apenas os arts. 20, 25-A, 25-B, 26, 27, 27-A e 27-B da Resolução 400 (informação, responsabilidade e assistência em atrasos, cancelamentos e interrupções). Os demais artigos citados nestes guias não mudam. [8]"},{"t":"p","text":"Foto de capa: Akshaya Nandyala / Pexels."},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Milhas sem mistério e quero cotar uma passagem."},{"t":"contato","title":"Fale com a gente no Direct do Instagram","text":"Tire dúvidas com a gente. Conte de onde você sai, para onde quer ir, o mês da viagem e quantas pessoas vão."}]', 7, datetime('now', '-0 minutes'));

-- Guia "Essa promoção é real? 10 conferências antes de pagar a passagem" (PUBLICADO). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/promocao-e-real.json.
-- Entra já publicado (--publicado): aparece em /blog/ assim que a migration for aplicada.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at)
VALUES ('69939745-806d-481a-90fe-53f769f7bd5f', 'promocao-e-real', 'published', 'dicas-de-viagem', 'Essa promoção é real? 10 conferências antes de pagar a passagem', 'é real', 'Checklist em 10 itens para conferir antes de comprar a sua passagem: preço final, bagagem, remarcação, escalas, nome, canal de compra e direitos básicos, com fontes oficiais conferidas em 22/10/2026.', 'Uma boa promoção continua boa depois de conferida. Marque cada item antes de pagar e guarde o guia em PDF no celular.', NULL, NULL, '/assets/blog/promocao-e-real.jpg', '/assets/blog/promocao-e-real-m.jpg', 'Celular de tela escura, sacola de papel e cartão sobre fundo verde azulado, visto de cima', 0, '[{"t":"pdf","href":"/guias/promocao-e-real.pdf","note":"Versão em PDF para guardar no celular. Grátis, sem cadastro."},{"t":"p","text":"Guia Rota Certa, atualizado em outubro de 2026, com fontes conferidas em 22/10/2026. Uma boa promoção continua boa depois de conferida: marque cada item antes de pagar."},{"t":"tip","items":["Um número entre colchetes, como [1], marca um fato com fonte oficial, listada em **Fontes**, no fim da página.","**Recomendação:** é um conselho da Rota Certa, não uma regra.","**Não verificado:** é um ponto que não conseguimos confirmar em fonte oficial."],"title":"Como ler este guia"},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Essa promoção é real? e quero ajuda para cotar uma passagem."},{"t":"h","text":"Antes de pagar","label":"Itens 1 a 3"},{"t":"p","text":"**1. Preço final, com taxas e impostos.** A oferta de passagem, em qualquer canal de venda, deve mostrar o valor total a pagar: serviço de transporte aéreo, tarifas aeroportuárias e valores devidos a órgãos do governo (art. 4). [1] Serviços opcionais, como despacho de bagagem, marcação de assento e seguro-viagem, só entram se você os contratar ativamente, e é proibido cobrar o que você não pediu (art. 4, §2º, e art. 5, §2º). [1, 2] **Recomendação:** compare o valor da primeira tela com o do último passo, antes de pagar."},{"t":"img","src":"/assets/blog/promocao-notebook-mesa.jpg","alt":"Pessoa digitando em notebook sobre mesa de madeira, com copo de água e revista","caption":"Compare o valor da primeira tela com o do último passo.","credit":"Foto: ROMAN ODINTSOV / Pexels","w":1000,"h":667},{"t":"p","text":"**2. Bagagem incluída.** A bagagem despachada é um contrato acessório: as companhias podem vender passagens com franquias diferentes ou sem franquia, e valem as regras do contrato (art. 13). [1, 3] A companhia deve permitir no mínimo 10 kg de bagagem de mão por passageiro, nas dimensões e na quantidade de peças definidas no contrato. Por segurança ou capacidade da aeronave, pode restringir peso e conteúdo (art. 14). [1, 3] **Recomendação:** procure na oferta o peso e as medidas da mala de mão e se a mala despachada está incluída."},{"t":"p","text":"**3. Remarcação e cancelamento.** Antes do pagamento, a companhia deve informar o valor total e as regras e multas de não comparecimento, remarcação e reembolso (art. 5, I e II). [1] As multas contratuais não podem passar do valor do transporte aéreo, e tarifas aeroportuárias e valores devidos a órgãos do governo ficam fora do cálculo (art. 9). [1] Em geral, tarifas mais baratas têm regras menos flexíveis e multas maiores, e as promocionais podem até não ser reembolsáveis. [2] **Recomendação:** pense quanto custaria mudar a data."},{"t":"h","text":"Datas, escalas e dados","label":"Itens 4 a 6"},{"t":"p","text":"**4. Datas e horários.** **Recomendação:** confira dia e horário de ida e de volta e o horário de chegada. Um voo que chega de madrugada ou sai muito cedo muda o gasto com transporte e hospedagem."},{"t":"p","text":"**5. Aeroporto de conexão e tempo de escala.** Antes do pagamento, a companhia deve informar o tempo de conexão, uma eventual troca de aeroportos e as regras e valores da bagagem (art. 5, III e IV). [1] **Recomendação:** desconfie de escala muito curta ou de troca de aeroporto, e confira se a mala vai até o destino final e se dá tempo de chegar ao próximo voo."},{"t":"img","src":"/assets/blog/promocao-mala-celular.jpg","alt":"Mulher caminhando ao ar livre com mala de rodinhas, olhando o celular","caption":"Confira escalas, horários e aeroportos antes de pagar.","credit":"Foto: Gustavo Fring / Pexels","w":1000,"h":667},{"t":"p","text":"**6. Nome igual ao do documento.** Erro no nome, sobrenome ou agnome deve ser corrigido sem ônus se você pedir até o check-in. Em voo internacional com mais de uma companhia (interline), o custo pode ser repassado, exceto se o erro foi da companhia. A correção não torna a passagem transferível (art. 8). [1] Erro na grafia do nome pode impedir o passageiro de viajar, por questões de segurança. [2] **Recomendação:** confira o nome letra por letra com o documento que você vai usar no embarque."},{"t":"h","text":"Confira a oferta","label":"Itens 7 a 10"},{"t":"p","text":"**7. Compare em mais de um canal.** **Recomendação:** busque o mesmo voo, nas mesmas datas e com a mesma bagagem, no site da companhia, em outra agência e em um buscador. Compare o total final, não o preço de vitrine."},{"t":"p","text":"**8. Cuidado com a pressão de tempo.** **Recomendação:** frases como só hoje e últimas vagas não substituem a conferência. Se a empresa não responde às suas perguntas antes do pagamento, é um bom motivo para parar."},{"t":"img","src":"/assets/blog/promocao-corredor-notebook.jpg","alt":"Homem sorrindo com notebook e celular, sentado no chão de um corredor com luz do sol","caption":"Compare o total final em mais de um canal, sem pressa.","credit":"Foto: Andrea Piacquadio / Pexels","w":1000,"h":667},{"t":"p","text":"**9. Link ou site desconhecido.** Um site de venda deve mostrar, em local de destaque, nome empresarial, CNPJ, endereço físico e eletrônico e as condições completas da oferta (art. 2º). [4] O Procon RS orienta pesquisar a reputação da loja e conferir o CNPJ no site da Receita Federal (desistir se aparecer baixada, cancelada ou inativa), ver se o endereço começa com https e tem cadeado, e desconfiar de ofertas milagrosas. [5] O Procon RS orienta usar só os canais oficiais das empresas e ver se endereço e CNPJ estão no rodapé do site. [6]"},{"t":"p","text":"**10. Guarde print e e-mail de confirmação.** **Recomendação:** tire print da oferta (preço, bagagem e regras) antes de pagar. O CDC garante informação clara sobre tributos e preço (art. 6º, III), e a informação ou publicidade suficientemente precisa obriga quem a divulga e integra o contrato (art. 30). [7] O Procon RS orienta gravar ou imprimir todos os passos da compra: e-mails, pedido, confirmação, cópia da oferta e comprovante de pagamento. [5]"},{"t":"h","text":"Seus direitos básicos"},{"t":"p","text":"**Mudou de ideia depois de comprar? Há duas regras.**"},{"t":"p","text":"**ANAC, passagem aérea.** Pela ANAC, você pode desistir da passagem sem ônus em até 24 horas, a contar do recebimento do comprovante, se a compra foi feita com antecedência igual ou superior a 7 dias em relação à data de embarque (art. 11). [1] A ANAC informa que a regra das 24 horas vale para compras por meios eletrônicos e em lojas físicas. Depois do prazo, a companhia pode cobrar multas, conforme as regras da passagem. [8]"},{"t":"p","text":"**Código de Defesa do Consumidor.** Pelo Código de Defesa do Consumidor, o consumidor pode desistir em 7 dias, a contar da assinatura ou do recebimento do serviço, quando a contratação ocorre fora do estabelecimento comercial, especialmente por telefone ou a domicílio. Os valores pagos voltam de imediato, atualizados (art. 49). [7] No comércio eletrônico, o fornecedor deve informar de forma clara e ostensiva como exercer o arrependimento, que pode ser pedido pela mesma ferramenta da compra (art. 5º). [4]"},{"t":"p","text":"**Não verificado:** não conseguimos confirmar qual das duas regras de desistência vale na compra online de passagem aérea: as 24 horas da ANAC (art. 11) ou os 7 dias do CDC (art. 49). As páginas oficiais abertas da ANAC e do Planalto não relacionam as duas regras. [7, 8]"},{"t":"p","text":"**Recomendação:** na dúvida, peça o cancelamento por escrito nas primeiras 24 horas e guarde o protocolo."},{"t":"img","src":"/assets/blog/promocao-mapa-anotacoes.jpg","alt":"Mãos sobre um mapa do mundo antigo, com chapéu, câmera instantânea e anotações de viagem","caption":"Guarde prints, e-mails e comprovantes de toda a compra.","credit":"Foto: Vlada Karpovich / Pexels","w":1000,"h":667},{"t":"p","text":"**E o reembolso?** A companhia tem 7 dias, a contar da sua solicitação, para reembolsar pelo mesmo meio de pagamento da compra. Tarifas aeroportuárias e valores devidos a órgãos do governo são devolvidos integralmente (art. 29). [1]"},{"t":"p","text":"**A empresa mudou o seu voo?** A companhia deve avisar mudanças programadas, como horário e itinerário, com no mínimo 72 horas de antecedência. Com aviso menor, ou com mudança de partida ou chegada acima de 30 minutos (voo doméstico) ou 1 hora (voo internacional) sem a sua concordância, você escolhe entre reacomodação e reembolso integral (art. 12). [1]"},{"t":"h","text":"Como reclamar"},{"t":"p","text":"Você pode reclamar na própria companhia, no Consumidor.gov.br, no Procon, no Juizado Especial Cível, na Defensoria Pública ou no Ministério Público. [9]"},{"t":"p","text":"O Consumidor.gov.br é um serviço público e gratuito de contato direto com empresas participantes, que se comprometem a responder em até 10 dias. [10]"},{"t":"img","src":"/assets/blog/promocao-mapa-aviaozinho.jpg","alt":"Mão segura um aviãozinho sobre um mapa do mundo azul, com passaporte, câmera e moedas","caption":"Com a oferta conferida, a viagem começa mais tranquila.","credit":"Foto: Tima Miroshnichenko / Pexels","w":1000,"h":667},{"t":"p","text":"Este guia informa e não substitui orientação jurídica. As regras mudam: confira sempre a versão da norma indicada em **Fontes**."},{"t":"pdf","href":"/guias/promocao-e-real.pdf","note":"Leve a lista de conferência no celular. Grátis, sem cadastro."},{"t":"h","text":"Não verificado"},{"t":"ul","items":["Não conseguimos confirmar qual das duas regras de desistência vale na compra online de passagem aérea: as 24 horas da ANAC (art. 11) ou os 7 dias do CDC (art. 49). As páginas oficiais abertas da ANAC e do Planalto não relacionam as duas regras. [7, 8]","**Bagagem.** Os limites de mala de mão além dos 10 kg da regra da ANAC, o peso e as medidas, e se a mala despachada vem incluída, variam por companhia e tarifa. O guia não afirma nenhum outro limite.","**Recomendações.** Comparar em mais de um canal, desconfiar de pressão de tempo, conferir datas, horários e escalas e conferir o nome com o documento de viagem são conselhos da Rota Certa. Nenhuma norma os impõe.","**Orientações dos Procons.** As dicas do Procon RS (2018 e 2023), do Procon Paulistano (arquivo de 2022) e do Procon de Contagem (2024) são orientações de órgãos de defesa do consumidor, com datas diferentes, e não regra federal."]},{"t":"tip","items":["[1] [ANAC, Resolução 400/2016, texto compilado (versão vigente em 22/10/2026), arts. 4, 5, 8, 9, 11, 12, 13, 14 e 29](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/resolucoes-2016/resolucao-no-400-13-12-2016)","[2] [ANAC, página Oferta e compra da passagem (atualizada em 13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/oferta-e-compra-da-passagem)","[3] [ANAC, página Bagagem (atualizada em 01/10/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/bagagem)","[4] [Decreto 7.962/2013 (comércio eletrônico), arts. 2º e 5º](https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/decreto/d7962.htm)","[5] [Procon RS, dicas de compras on-line (15/02/2018)](https://procon.rs.gov.br/fique-atento-as-dicas-do-procon-rs-sobre-compras-on-line)","[6] [Procon RS, sinais de golpes e fraudes na compra (08/04/2023)](https://procon.rs.gov.br/proconrsexplica-o-que-fazer-diante-dos-sinais-de-golpes-e-fraudes-no-momento-da-compra)","[7] [Código de Defesa do Consumidor, Lei 8.078/1990, texto compilado, art. 49](https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm)","[8] [ANAC, página Alterações da viagem e reembolso (atualizada em 13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/alteracoes-da-viagem)","[9] [Procon Paulistano (Prefeitura de São Paulo), Cartilha do Transporte Aéreo (arquivo de 2022)](https://prefeitura.sp.gov.br/documents/d/procon/cartilha-transporte-aereo-procon)","[10] [Senacon, Consumidor.gov.br](https://www.consumidor.gov.br/pages/conteudo/publico/1)","[11] [ANAC, Resolução 800/2026 (passageiro indisciplinado; alterou os arts. 5 e 18 da Res. 400)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-800)","[12] [ANAC, Resolução 813/2026 (altera a Res. 400; vale a partir de 26/10/2026)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-813)"],"title":"Fontes, conferidas em 22/10/2026"},{"t":"p","text":"**Versão da norma.** Resolução ANAC 400/2016, texto compilado no site da ANAC (última modificação em 26/08/2026, com as Resoluções 434/2017, 692/2022 e 800/2026 [11]), vigente em 22/10/2026. Os artigos citados são os dessa versão. A Resolução ANAC 813/2026 só vale a partir de 26/10/2026 e altera apenas os arts. 20, 25-A, 25-B, 26, 27, 27-A e 27-B da Resolução 400 (informação, responsabilidade e assistência em atrasos, cancelamentos e interrupções). Os demais artigos citados nestes guias não mudam. [12]"},{"t":"p","text":"Foto de capa: Nataliya Vaitkevich / Pexels."},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Essa promoção é real? e quero ajuda para cotar uma passagem."},{"t":"contato","title":"Fale com a gente no Direct do Instagram","text":"Tire dúvidas com a gente. Conte de onde você sai, para onde quer ir, o mês da viagem e quantas pessoas vão."}]', 8, datetime('now', '-1 minutes'));

-- Guia "Erros que encarecem sua passagem: 8 para evitar antes de comprar" (PUBLICADO). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/erros-ao-comprar-passagem.json.
-- Entra já publicado (--publicado): aparece em /blog/ assim que a migration for aplicada.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at)
VALUES ('77965e0b-4751-4ac8-bd61-a4e75579f22a', 'erros-ao-comprar-passagem', 'published', 'dicas-de-viagem', 'Erros que encarecem sua passagem: 8 para evitar antes de comprar', 'encarecem', '8 erros comuns na hora de comprar passagem aérea, como evitar cada um e o que conferir agora, com fontes oficiais conferidas em 22/10/2026 e uma lista final para marcar antes de pagar.', 'Cada erro traz o que acontece, como evitar e uma conferência rápida para fazer agora.', NULL, NULL, '/assets/blog/erros-ao-comprar-passagem.jpg', '/assets/blog/erros-ao-comprar-passagem-m.jpg', 'Mulher de boné sentada em cadeiras azuis de aeroporto, com mala de mão ao lado', 0, '[{"t":"pdf","href":"/guias/erros-ao-comprar-passagem.pdf","note":"Versão em PDF para guardar no celular. Grátis, sem cadastro."},{"t":"p","text":"Guia Rota Certa, atualizado em outubro de 2026, com fontes conferidas em 22/10/2026. São 8 erros comuns na hora de comprar passagem aérea, como evitar cada um e o que conferir agora."},{"t":"tip","items":["Um número entre colchetes, como [1], marca um fato com fonte oficial, listada em **Fontes**, no fim da página.","**Recomendação:** é um conselho da Rota Certa, não uma regra.","**Não verificado:** é um ponto que não conseguimos confirmar em fonte oficial."],"title":"Como ler este guia"},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Erros que encarecem sua passagem e quero ajuda para cotar uma passagem."},{"t":"h","text":"Comprar sem comparar datas","label":"Erro 1"},{"t":"p","text":"**O que acontece.** Sem comparar, você não sabe se outra data serve melhor."},{"t":"p","text":"**Como evitar.** **Recomendação:** teste ida e volta em dias da semana diferentes e varie a data em alguns dias. Compare sempre o total final de cada opção, com taxas."},{"t":"tip","items":["Mude as datas em 2 ou 3 dias e anote o total de cada opção."],"title":"Confira agora"},{"t":"h","text":"Ignorar a regra de bagagem da tarifa","label":"Erro 2"},{"t":"p","text":"**O que acontece.** A companhia deve permitir no mínimo 10 kg de bagagem de mão por passageiro, nas dimensões e na quantidade de peças definidas no contrato. Por segurança ou capacidade da aeronave, pode restringir peso e conteúdo (art. 14). [1, 2] A bagagem despachada é um contrato acessório: as companhias podem vender passagens com franquias diferentes ou sem franquia, e valem as regras do contrato (art. 13). [1, 2]"},{"t":"img","src":"/assets/blog/erros-corredor-aeroporto.jpg","alt":"Corredor claro de aeroporto com viajante puxando mala de rodinhas e salas de espera ao fundo","caption":"Peso, medidas e mala despachada: confira o que a tarifa inclui.","credit":"Foto: Kenneth Surillo / Pexels","w":1000,"h":667},{"t":"p","text":"**Como evitar.** Em geral, tarifas mais baratas têm regras menos flexíveis e multas maiores, e as promocionais podem até não ser reembolsáveis. [3] **Recomendação:** compare tarifas com a mesma bagagem."},{"t":"tip","items":["Peso, medidas e se há mala despachada na tarifa."],"title":"Confira agora"},{"t":"h","text":"Nome diferente do documento","label":"Erro 3"},{"t":"p","text":"**O que acontece.** Erro no nome, sobrenome ou agnome deve ser corrigido sem ônus se você pedir até o check-in. Em voo internacional com mais de uma companhia (interline), o custo pode ser repassado, exceto se o erro foi da companhia. A correção não torna a passagem transferível (art. 8). [1] Erro na grafia do nome pode impedir o passageiro de viajar, por questões de segurança. [3]"},{"t":"p","text":"**Como evitar.** **Recomendação:** copie o nome exatamente como está no documento que você vai levar."},{"t":"tip","items":["Compare, letra por letra, o comprovante com o passaporte."],"title":"Confira agora"},{"t":"h","text":"Esquecer taxas e extras","label":"Erro 4"},{"t":"p","text":"**O que acontece.** A oferta de passagem, em qualquer canal de venda, deve mostrar o valor total a pagar: serviço de transporte aéreo, tarifas aeroportuárias e valores devidos a órgãos do governo (art. 4). [1] Serviços opcionais, como despacho de bagagem, marcação de assento e seguro-viagem, só entram se você os contratar ativamente, e é proibido cobrar o que você não pediu (art. 4, §2º, e art. 5, §2º). [1, 3]"},{"t":"p","text":"**Como evitar.** **Recomendação:** some o assento e a bagagem que você vai usar antes de comparar preços."},{"t":"tip","items":["Na última tela, leia o total e desmarque o que não pediu."],"title":"Confira agora"},{"t":"h","text":"Não conferir aeroporto e conexão","label":"Erro 5"},{"t":"p","text":"**O que acontece.** Antes do pagamento, a companhia deve informar o tempo de conexão, uma eventual troca de aeroportos e as regras e valores da bagagem (art. 5, III e IV). [1] Em voo com conexão, se você perder o voo seguinte por causa da companhia, inclusive com troca de aeroportos, ela deve oferecer reacomodação, reembolso ou outro transporte, à sua escolha (art. 21). [1]"},{"t":"img","src":"/assets/blog/erros-painel-de-voos.jpg","alt":"Mulher de costas olhando um painel de voos desfocado, com luzes quentes ao fundo","caption":"Releia os códigos de aeroporto e o tempo entre os voos.","credit":"Foto: Gustavo Fring / Pexels","w":1000,"h":667},{"t":"p","text":"**Como evitar.** **Recomendação:** olhe o código do aeroporto de cada trecho e dê folga à conexão, ainda mais se houver imigração."},{"t":"tip","items":["Releia os códigos de aeroporto e o tempo entre os voos."],"title":"Confira agora"},{"t":"h","text":"Deixar documento ou visto para depois","label":"Erro 6"},{"t":"p","text":"**O que acontece.** Para embarcar, você deve apresentar documento de identificação civil e cumprir as exigências da viagem, como o visto correto e os certificados de vacinação exigidos pelos países de destino, escala e conexão. Se não cumprir, a companhia pode negar o embarque (arts. 16 e 18). [1]"},{"t":"img","src":"/assets/blog/erros-passaporte-na-mala.jpg","alt":"Mala turquesa com um passaporte verde apoiado na alça, em saguão de aeroporto desfocado","caption":"Compare a validade do passaporte com a data da volta.","credit":"Foto: Yazid N / Pexels","w":1000,"h":667},{"t":"p","text":"**Como evitar.** O prazo estimado de entrega do passaporte é, em geral, de 6 a 10 dias úteis depois do atendimento presencial. Perto de férias escolares e feriados prolongados, o atendimento pode demorar mais. [4] Para entrar na União Europeia, o passaporte deve valer por pelo menos 3 meses depois da data prevista de saída e ter sido emitido nos últimos 10 anos. Conforme a nacionalidade, pode ser preciso visto. [5] **Recomendação:** confira cada destino em fonte oficial."},{"t":"tip","items":["Compare a validade do passaporte com a data da volta."],"title":"Confira agora"},{"t":"h","text":"Não guardar comprovantes","label":"Erro 7"},{"t":"p","text":"**O que acontece.** O comprovante da passagem traz nome e sobrenome do passageiro, data e horário do voo, horário de embarque, produtos e serviços comprados e prazo de validade (art. 6). [1] Esse é o comprovante que conta para o prazo de desistência (veja a seção sobre desistência, mais abaixo)."},{"t":"p","text":"**Como evitar.** **Recomendação:** salve o PDF, o código localizador e uma captura das regras da tarifa onde abra sem internet. O Procon RS orienta gravar ou imprimir todos os passos da compra: e-mails, pedido, confirmação, cópia da oferta e comprovante de pagamento. [6]"},{"t":"img","src":"/assets/blog/erros-telefone-terminal.jpg","alt":"Mulher sorrindo ao telefone ao lado de painéis de informação em terminal de aeroporto","caption":"Salve o comprovante e o código localizador onde abra sem internet.","credit":"Foto: Holiday Extras / Pexels","w":1000,"h":667},{"t":"tip","items":["Ache o comprovante no e-mail e salve uma cópia no celular."],"title":"Confira agora"},{"t":"h","text":"Comprar em canal desconhecido","label":"Erro 8"},{"t":"p","text":"**O que acontece.** O Procon Paulistano orienta conferir sempre se o site em que você navega é confiável e seguro. [7] O Procon de Contagem (MG) orienta checar CNPJ, endereço físico e avaliações, desconfiar de preço muito abaixo do mercado, evitar links de SMS, e-mail ou redes sociais e confirmar que o Pix vai para o nome da empresa. [8]"},{"t":"p","text":"**Como evitar.** **Recomendação:** digite o endereço do site você mesmo e confira o código localizador no site da companhia. O Consumidor.gov.br é um serviço público e gratuito de contato direto com empresas participantes, que se comprometem a responder em até 10 dias. [9]"},{"t":"tip","items":["Veja se quem recebe o pagamento é a empresa."],"title":"Confira agora"},{"t":"h","text":"Desistência e checklist"},{"t":"p","text":"**Mudou de ideia depois de comprar? Há duas regras.**"},{"t":"p","text":"**ANAC, passagem aérea.** Pela ANAC, você pode desistir da passagem sem ônus em até 24 horas, a contar do recebimento do comprovante, se a compra foi feita com antecedência igual ou superior a 7 dias em relação à data de embarque (art. 11). [1] A ANAC informa que a regra das 24 horas vale para compras por meios eletrônicos e em lojas físicas. Depois do prazo, a companhia pode cobrar multas, conforme as regras da passagem. [10]"},{"t":"p","text":"**Código de Defesa do Consumidor.** Pelo Código de Defesa do Consumidor, o consumidor pode desistir em 7 dias, a contar da assinatura ou do recebimento do serviço, quando a contratação ocorre fora do estabelecimento comercial, especialmente por telefone ou a domicílio. Os valores pagos voltam de imediato, atualizados (art. 49). [11] No comércio eletrônico, o fornecedor deve informar de forma clara e ostensiva como exercer o arrependimento, que pode ser pedido pela mesma ferramenta da compra (art. 5º). [12]"},{"t":"p","text":"**Não verificado:** não conseguimos confirmar qual das duas regras de desistência vale na compra online de passagem aérea: as 24 horas da ANAC (art. 11) ou os 7 dias do CDC (art. 49). As páginas oficiais abertas da ANAC e do Planalto não relacionam as duas regras. [10, 11]"},{"t":"p","text":"**Recomendação:** na dúvida, peça o cancelamento por escrito nas primeiras 24 horas e guarde o protocolo."},{"t":"img","src":"/assets/blog/erros-controle-de-seguranca.jpg","alt":"Passageira de costas num corredor de segurança de aeroporto, sob estrutura iluminada em verde e azul","caption":"Antes de pagar, marque cada item da lista abaixo.","credit":"Foto: Matthew Turner / Pexels","w":1000,"h":667},{"t":"tip","items":["☐ Datas vizinhas comparadas","☐ Bagagem da tarifa lida","☐ Nome igual ao do passaporte","☐ Total final conferido, sem extras que você não pediu","☐ Aeroportos e tempo de conexão conferidos","☐ Passaporte e regras do destino conferidos","☐ Comprovante e código localizador salvos","☐ Canal de compra conferido"],"title":"Checklist antes de pagar"},{"t":"pdf","href":"/guias/erros-ao-comprar-passagem.pdf","note":"Leve os 8 erros e o checklist no celular. Grátis, sem cadastro."},{"t":"h","text":"Não verificado"},{"t":"ul","items":["Não conseguimos confirmar qual das duas regras de desistência vale na compra online de passagem aérea: as 24 horas da ANAC (art. 11) ou os 7 dias do CDC (art. 49). As páginas oficiais abertas da ANAC e do Planalto não relacionam as duas regras. [10, 11]","**Comparar datas e dias da semana.** Que isso mude o preço é prática da Rota Certa, sem fonte oficial. Não prometemos economia.","**Tempo ideal de conexão.** Varia por aeroporto, companhia e tipo de voo. Não achamos fonte oficial com um tempo único.","**Reservas separadas.** Quem responde quando os trechos são comprados em reservas separadas: sem fonte oficial.","**Bagagem de cada companhia.** Peso, medidas e valores variam por tarifa. Não confirmamos se algum projeto de lei sobre bagagem despachada gratuita virou lei: este guia segue a Resolução 400 na versão indicada em **Fontes**.","**Entrada em cada destino.** Não verificamos as regras atuais, como o visto dos EUA. Exemplo datado: em 22/10/2026, o site oficial da UE informa que o ETIAS, autorização eletrônica para quem não precisa de visto, ainda não está em operação, e que a data de início será avisada com meses de antecedência. [13] Confira cada destino em fonte oficial antes de comprar.","**Orientações dos Procons.** As dicas do Procon Paulistano (arquivo de 2022), do Procon RS (2018) e do Procon de Contagem (2024) são orientações de órgãos de defesa do consumidor, e não regra federal."]},{"t":"tip","items":["[1] [ANAC, Resolução 400/2016, texto compilado (versão vigente em 22/10/2026), arts. 4, 5, 6, 8, 11, 13, 14, 16, 18 e 21](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/resolucoes-2016/resolucao-no-400-13-12-2016)","[2] [ANAC, página Bagagem (atualizada em 01/10/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/bagagem)","[3] [ANAC, página Oferta e compra da passagem (atualizada em 13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/oferta-e-compra-da-passagem)","[4] [gov.br, serviço Obter passaporte (Polícia Federal, última modificação 07/10/2026)](https://www.gov.br/pt-br/servicos/obter-passaporte-comum-para-brasileiro)","[5] [União Europeia, Your Europe, documentos de viagem para não europeus](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm)","[6] [Procon RS, dicas de compras on-line (15/02/2018)](https://procon.rs.gov.br/fique-atento-as-dicas-do-procon-rs-sobre-compras-on-line)","[7] [Procon Paulistano (Prefeitura de São Paulo), Cartilha do Transporte Aéreo (arquivo de 2022)](https://prefeitura.sp.gov.br/documents/d/procon/cartilha-transporte-aereo-procon)","[8] [Procon de Contagem (MG), golpes em pacotes de viagem (21/12/2024)](https://portal.contagem.mg.gov.br/portal/noticias/0/3/80889/golpes-em-pacotes-de-viagem-procon-contagem-orienta-consumidores-a-evitarem-fraudes)","[9] [Senacon, Consumidor.gov.br](https://www.consumidor.gov.br/pages/conteudo/publico/1)","[10] [ANAC, página Alterações da viagem e reembolso (atualizada em 13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/alteracoes-da-viagem)","[11] [Código de Defesa do Consumidor, Lei 8.078/1990, texto compilado, art. 49](https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm)","[12] [Decreto 7.962/2013 (comércio eletrônico), art. 5º](https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/decreto/d7962.htm)","[13] [União Europeia, site oficial do ETIAS](https://travel-europe.europa.eu/en/etias)","[14] [ANAC, Resolução 800/2026 (passageiro indisciplinado; alterou os arts. 5 e 18 da Res. 400)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-800)","[15] [ANAC, Resolução 813/2026 (altera a Res. 400; vale a partir de 26/10/2026)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-813)"],"title":"Fontes, conferidas em 22/10/2026"},{"t":"p","text":"**Versão da norma.** Resolução ANAC 400/2016, texto compilado no site da ANAC (última modificação em 26/08/2026, com as Resoluções 434/2017, 692/2022 e 800/2026 [14]), vigente em 22/10/2026. Os artigos citados são os dessa versão. A Resolução ANAC 813/2026 só vale a partir de 26/10/2026 e altera apenas os arts. 20, 25-A, 25-B, 26, 27, 27-A e 27-B da Resolução 400 (informação, responsabilidade e assistência em atrasos, cancelamentos e interrupções). Os demais artigos citados nestes guias não mudam. [15]"},{"t":"p","text":"Foto de capa: Kenneth Surillo / Pexels."},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Erros que encarecem sua passagem e quero ajuda para cotar uma passagem."},{"t":"contato","title":"Fale com a gente no Direct do Instagram","text":"Tire dúvidas com a gente. Conte de onde você sai, para onde quer ir, o mês da viagem e quantas pessoas vão."}]', 9, datetime('now', '-2 minutes'));

-- Guia "Modelo de roteiro de viagem: 8 passos e um dia em branco para preencher" (PUBLICADO). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/modelo-de-roteiro.json.
-- Entra já publicado (--publicado): aparece em /blog/ assim que a migration for aplicada.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at)
VALUES ('bccb3155-54c6-41f5-845a-202adec7ae2a', 'modelo-de-roteiro', 'published', 'dicas-de-viagem', 'Modelo de roteiro de viagem: 8 passos e um dia em branco para preencher', '8 passos', 'Um método em 8 passos para montar o roteiro de viagem, um modelo de dia em branco para preencher e um exemplo pronto, com o guia em PDF de campos preenchíveis para baixar de graça.', 'Comece pelo que importa e deixe o resto caber: escolha 3 lugares, agrupe por região, deixe tempo livre e tenha um plano B.', NULL, NULL, '/assets/blog/modelo-de-roteiro.jpg', '/assets/blog/modelo-de-roteiro-m.jpg', 'Casal sentado em um banco ao sol, consultando um mapa de papel em um terraço', 0, '[{"t":"pdf","href":"/guias/modelo-de-roteiro.pdf","note":"Versão em PDF, com as células do modelo preenchíveis. Grátis, sem cadastro."},{"t":"p","text":"Guia Rota Certa, atualizado em outubro de 2026, com fontes conferidas em 22/10/2026. É um método em 8 passos, um modelo de dia em branco para preencher e um exemplo pronto. Comece pelo que importa e deixe o resto caber."},{"t":"tip","items":["Um número entre colchetes, como [1], marca um fato com fonte oficial, listada em **Fontes**, no fim da página.","**Recomendação:** é um conselho da Rota Certa, não uma regra.","**Não verificado:** é um ponto que não conseguimos confirmar em fonte oficial.","O método deste guia é todo Recomendação da Rota Certa: não há norma de viagem por trás dele. Só os dois exemplos do Museu Reina Sofía têm fonte."],"title":"Como ler este guia"},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Modelo de roteiro de viagem e quero cotar uma passagem."},{"t":"h","text":"8 passos para montar o roteiro"},{"t":"p","text":"**1. Escolha 3 lugares que não podem faltar.** Pense na viagem inteira e escreva só três. Eles são os principais e entram primeiro no roteiro. Todo o resto é bônus."},{"t":"img","src":"/assets/blog/roteiro-camera-e-mapa.jpg","alt":"Mapa do mundo claro com câmera analógica, bússola, flores e caderno de carimbos de viagem","caption":"Escolha só três lugares que não podem faltar e comece por eles.","credit":"Foto: Nataliya Vaitkevich / Pexels","w":1000,"h":667},{"t":"p","text":"**2. Agrupe por região.** Marque tudo no mapa e junte o que fica perto. Uma região por dia poupa transporte e deixa mais tempo para ver."},{"t":"img","src":"/assets/blog/roteiro-mapa-de-papel.jpg","alt":"Dedo apontando um ponto em um mapa urbano de papel, com ruas e rio coloridos","caption":"Marque tudo no mapa e junte o que fica perto.","credit":"Foto: ClickerHappy / Pexels","w":1000,"h":667},{"t":"p","text":"**3. Deixe tempo livre.** Reserve um bloco sem plano em cada dia, para um café, um banco de praça ou uma rua sem destino. **Recomendação:** 3 ou 4 paradas por dia, não mais."},{"t":"img","src":"/assets/blog/roteiro-rua-de-pedra.jpg","alt":"Casal caminhando por uma rua estreita de pedra entre casas antigas","caption":"Um bloco sem plano em cada dia: uma rua sem destino também é passeio.","credit":"Foto: Jan van der Wolf / Pexels","w":1000,"h":667},{"t":"p","text":"**4. Confira dias e horários.** Museus e palácios podem fechar em dias fixos e mudar o horário no domingo. Veja o site oficial do lugar, perto da data. Exemplo conferido em 22/10/2026: o site do Museu Reina Sofía, em Madri, informa que a sede principal fica fechada às terças-feiras (a tabela de horários mostra Martes: Cerrado). [1]"},{"t":"p","text":"**5. Organize manhã, tarde e noite.** Manhã para o que pede mais energia ou lota. Tarde para a segunda parada e um almoço sem pressa. Noite para jantar e passeio leve."},{"t":"img","src":"/assets/blog/roteiro-cidade-do-alto.jpg","alt":"Vista do alto de uma cidade com telhados, rio e colinas ao fundo, em luz de fim de tarde","caption":"Manhã, tarde e noite: cada parte do dia com o seu ritmo.","credit":"Foto: Talha Kılıç / Pexels","w":1000,"h":667},{"t":"p","text":"**6. Planeje deslocamentos e margem.** Em cada trecho, anote como ir (a pé, transporte público, táxi) e o tempo no mapa. **Recomendação:** some uma margem de 15 minutos por trecho para atrasos."},{"t":"img","src":"/assets/blog/roteiro-rua-de-pedestres.jpg","alt":"Rua de pedestres com prédios históricos, castelo em uma colina e céu azul ao fundo","caption":"Em cada trecho, anote como ir e o tempo no mapa.","credit":"Foto: Alexander Nadrilyanski / Pexels","w":1000,"h":667},{"t":"p","text":"**7. Separe grátis, pagos e opcionais.** Marque cada parada com uma etiqueta (**Grátis**, **Pago** ou **Opcional**) e some só os pagos. Opcional entra se sobrar tempo."},{"t":"p","text":"**8. Tenha um plano B para chuva.** Em cada dia, tenha uma opção coberta na mesma região (museu, mercado, café). Se chover, troque os dias: o passeio ao ar livre fica para outro. Exemplo conferido em 22/10/2026: o site do Reina Sofía avisa que o Palácio de Cristal, no Parque do Retiro, pode permanecer fechado em dias de chuva e de alerta de calor. A mesma página informa que ele está fechado temporariamente por obras de melhoria. [1]"},{"t":"img","src":"/assets/blog/roteiro-mirante.jpg","alt":"Mirante com cerca de madeira sobre a encosta, com cidade e lagoa ao fundo em luz dourada","caption":"Um mirante no fim do dia entra como opcional, se sobrar tempo.","credit":"Foto: Riccardo Pitzalis / Pexels","w":1000,"h":667},{"t":"h","text":"Modelo de um dia"},{"t":"ul","items":["**Dia e data:** ____","**Região:** ____","**Os 3 principais:** ____"]},{"t":"p","text":"Preencha cada linha do dia com **lugar, como chegar, tempo, custo estimado e plano B**:"},{"t":"ul","items":["**Manhã:** ____","**Manhã:** ____","**Almoço:** ____","**Tarde:** ____","**Tarde:** ____","**Noite:** ____","**Noite:** ____"]},{"t":"ul","items":["**Tempo livre:** ____","**Margem de atraso:** ____","**Se chover:** ____","**Total estimado:** ____"]},{"t":"p","text":"Em Custo, escreva grátis, pago ou opcional e o valor estimado. Confira os horários no site oficial e anote a data da checagem. No PDF, as células são campos preenchíveis."},{"t":"h","text":"Um dia preenchido"},{"t":"p","text":"Exemplo genérico, sem lugar real. Os horários são do plano de quem viaja, não de funcionamento."},{"t":"ul","items":["**9h00, museu principal.** Como chegar: metrô, 20 min. Tempo: 2h. Custo: pago. Plano B: já é coberto.","**11h30, praça ao lado.** Como chegar: a pé, 5 min. Tempo: 45 min. Custo: grátis. Plano B: café na rua.","**12h30, almoço no mercado.** Como chegar: a pé, 10 min. Tempo: 1h30. Custo: pago. Plano B: mercado é coberto.","**15h00, igreja ou palácio.** Como chegar: a pé, 15 min. Tempo: 1h30. Custo: pago. Plano B: museu menor.","**17h00, tempo livre.** Como chegar: no lugar. Tempo: 1h30. Custo: grátis. Plano B: livraria ou café.","**19h00, mirante do pôr do sol.** Como chegar: táxi, 15 min. Tempo: 1h. Custo: opcional. Plano B: pular e jantar antes.","**20h30, jantar perto do hotel.** Como chegar: a pé, 10 min. Tempo: 1h30. Custo: pago. Plano B: reserva coberta."]},{"t":"p","text":"Repare: uma região só, três paradas principais, folga entre elas e um plano B para cada parada."},{"t":"pdf","href":"/guias/modelo-de-roteiro.pdf","note":"Baixe o modelo de dia com campos preenchíveis. Grátis, sem cadastro."},{"t":"h","text":"Não verificado"},{"t":"ul","items":["**Lugares.** Horários, preços e regras de qualquer lugar, exceto os dois exemplos do Reina Sofía: confirme no site oficial. Os exemplos foram lidos em 22/10/2026 e podem mudar.","**Deslocamentos.** Os tempos variam com o trajeto, o dia e o horário. Confira no mapa.","**Margens sugeridas.** As margens de 15 minutos por trecho e de 3 ou 4 paradas por dia são regra prática da Rota Certa, não dado oficial."]},{"t":"tip","items":["[1] [Museu Reina Sofía, horários e tarifas](https://www.museoreinasofia.es/visita/horarios-tarifas/)"],"title":"Fontes, conferidas em 22/10/2026"},{"t":"p","text":"Foto de capa: Kampus Production / Pexels."},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Modelo de roteiro de viagem e quero cotar uma passagem."},{"t":"contato","title":"Fale com a gente no Direct do Instagram","text":"Tire dúvidas com a gente. Conte de onde você sai, para onde quer ir, o mês da viagem e quantas pessoas vão."}]', 4, datetime('now', '-3 minutes'));

-- Guia "Checklist antes de viajar: documentos, mala, dinheiro e saúde" (PUBLICADO). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/checklist-antes-de-viajar.json.
-- Entra já publicado (--publicado): aparece em /blog/ assim que a migration for aplicada.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at)
VALUES ('da0bd53c-0c03-4293-bf10-6cf8018bc9b1', 'checklist-antes-de-viajar', 'published', 'dicas-de-viagem', 'Checklist antes de viajar: documentos, mala, dinheiro e saúde', 'Checklist antes de viajar', 'Documentos, passagens, dinheiro, saúde, mala, celular e uma linha do tempo de 60, 30, 7 e 1 dia antes, com caixinhas para marcar e fontes oficiais conferidas em 22/10/2026.', 'Regras mudam. Use este guia como roteiro e confirme os pontos que dependem do seu destino, da sua companhia aérea e da sua data de viagem.', NULL, NULL, '/assets/blog/checklist-antes-de-viajar.jpg', '/assets/blog/checklist-antes-de-viajar-m.jpg', 'Mulher de fones arrumando uma mala aberta no chão de uma sala clara', 0, '[{"t":"pdf","href":"/guias/checklist-antes-de-viajar.pdf","note":"Versão em PDF com caixinhas para marcar. Grátis, sem cadastro."},{"t":"p","text":"Guia Rota Certa, atualizado em outubro de 2026, com fontes conferidas em 22/10/2026. Regras mudam: use este guia como roteiro e confirme os pontos que dependem do seu destino, da sua companhia aérea e da sua data de viagem. **Quem decide o que você precisa para entrar é o país de destino.** Confira sempre no site oficial dele."},{"t":"tip","items":["Um número entre colchetes, como [1], marca um fato com fonte oficial, listada em **Fontes**, no fim da página.","**Recomendação:** é um conselho da Rota Certa, não uma regra.","**Não verificado:** é um ponto que não conseguimos confirmar em fonte oficial.","☐ marca um item para você conferir."],"title":"Como ler este guia"},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Checklist antes de viajar e quero cotar uma passagem."},{"t":"h","text":"Passaporte e identidade"},{"t":"p","text":"**Passaporte.** O passaporte comum tem validade de 10 anos para maiores de 18 anos e de 5 anos para quem tem de 4 a 18 anos. No Brasil não existe renovação: com o passaporte vencido, emite-se outro. [1, 2] O pedido é feito no site da Polícia Federal (formulário, taxa, agendamento e atendimento presencial com biometria). Não é preciso pagar assessoria. [1, 2] O prazo estimado de entrega do passaporte é, em geral, de 6 a 10 dias úteis depois do atendimento presencial. Perto de férias escolares e feriados prolongados, o atendimento pode demorar mais. [1]"},{"t":"p","text":"**Recomendação:** confira a validade do passaporte antes de comprar a passagem."},{"t":"ul","items":["☐ Passaporte na validade que o país de destino pede.","☐ Nome do passaporte igual ao da passagem."]},{"t":"img","src":"/assets/blog/checklist-passaporte-e-bussola.jpg","alt":"Passaporte decorativo de carimbos e bússola sobre mapa do mundo, com flores e chapéu de palha","caption":"Confira a validade do passaporte antes de comprar a passagem.","credit":"Foto: Nataliya Vaitkevich / Pexels","w":1000,"h":667},{"t":"p","text":"**Só o documento de identidade?** Em viagem de turismo ao Mercosul, a Polícia Federal dispensa o passaporte se você apresentar RG emitido há menos de 10 anos, com foto que ainda identifique você. CNH, carteiras de conselhos e certidão não servem. Trabalho, estudo, residência e saúde exigem passaporte. [2] A ANAC lista Argentina, Uruguai, Paraguai, Bolívia, Chile, Peru, Equador, Colômbia e Venezuela como destinos em que o RG também é aceito. [3] A CIN tem leitura por máquina, como o passaporte, e é aceita nos países com acordo de viagens, como os do Mercosul. Ela não substitui o passaporte nos demais países. [4]"},{"t":"p","text":"**Recomendação:** na dúvida, confirme com a companhia e com o país. A Rota Certa prefere o passaporte."},{"t":"ul","items":["☐ Documento aceito no destino, conferido na fonte oficial."]},{"t":"p","text":"**Menor de 18 anos?** Menor de 18 anos com um dos pais: passaporte e autorização expressa do outro genitor, com firma reconhecida. Desacompanhado ou com adulto autorizado: autorização de ambos os pais. A ANAC remete à cartilha do CNJ e da Polícia Federal. [5]"},{"t":"h","text":"Visto, vacina e seguro"},{"t":"p","text":"**Visto ou autorização eletrônica.** O passaporte brasileiro isenta de visto de turismo em mais de 150 países, mas as autoridades podem pedir comprovante de hospedagem, carta-convite e passagem de volta, e o país de conexão também pode exigir visto. Visto incorreto para o objetivo da viagem pode levar à detenção. [6]"},{"t":"p","text":"Exemplo datado: em 22/10/2026, o site oficial da UE informa que o ETIAS, autorização eletrônica para quem não precisa de visto, ainda não está em operação, e que a data de início será avisada com meses de antecedência. [7]"},{"t":"p","text":"Para embarcar, você deve apresentar documento de identificação civil e cumprir as exigências da viagem, como o visto correto e os certificados de vacinação exigidos pelos países de destino, escala e conexão. Se não cumprir, a companhia pode negar o embarque (arts. 16 e 18). [8]"},{"t":"ul","items":["☐ Visto ou autorização (e conexão) conferidos no site do governo ou na embaixada."]},{"t":"p","text":"**Certificado de vacinação (CIVP).** Alguns países exigem o certificado de vacinação contra febre amarela (CIVP). Ele vale a partir de 10 dias depois da vacina e por toda a vida. Pode estar no app Meu SUS Digital; se não estiver, peça no gov.br com CPF. A página do serviço remete à lista da OMS dos países que exigem o certificado e manda conferir todos os países do trajeto, se houver escala ou conexão. [9]"},{"t":"ul","items":["☐ CIVP exigido? Conferi destino e conexões.","☐ Vacina aplicada 10 dias ou mais antes."]},{"t":"p","text":"**Seguro viagem.** No seguro viagem internacional, a cobertura deve incluir ao menos despesas médicas, hospitalares e odontológicas, e não pode cobrir só acidentes pessoais. [10]"},{"t":"p","text":"**Recomendação:** contrate seguro mesmo se o país não exigir e leia o que a apólice cobre."},{"t":"ul","items":["☐ Apólice salva no celular, com o telefone da seguradora."]},{"t":"h","text":"Passagens e reservas"},{"t":"ul","items":["**Nome.** Erro no nome, sobrenome ou agnome deve ser corrigido sem ônus se você pedir até o check-in. Em voo internacional com mais de uma companhia (interline), o custo pode ser repassado, exceto se o erro foi da companhia. A correção não torna a passagem transferível (art. 8). [8]","**Bagagem.** A bagagem despachada é um contrato acessório: as companhias podem vender passagens com franquias diferentes ou sem franquia, e valem as regras do contrato (art. 13). [8, 11]","**Check-in.** O passageiro deve se apresentar para embarque com documento de identificação civil e no horário estabelecido pela companhia (art. 18, I). [8]","**Ida e volta.** Na passagem de ida e volta, se você não usar o trecho inicial, a companhia pode cancelar o trecho de volta. Em voo doméstico, se você avisar até o horário do voo de ida que quer usar a volta, ela não pode cobrar multa por isso (art. 19). [8]"]},{"t":"p","text":"**Recomendação:** veja no e-mail ou no app quando o check-in abre e fecha e chegue com folga."},{"t":"ul","items":["☐ Nome do bilhete conferido letra por letra.","☐ Sei o que a tarifa inclui de bagagem.","☐ Horário de check-in anotado."]},{"t":"h","text":"Dinheiro e cartões"},{"t":"p","text":"**Recomendação:** avise o banco ou veja no app se o cartão vale no exterior. Confira moeda e limite, e leve mais de um meio de pagamento, em lugares separados. Veja tomada e voltagem do destino."},{"t":"ul","items":["☐ Cartão liberado no exterior, limite conferido.","☐ Moeda definida e adaptador de tomada na mala."]},{"t":"p","text":"**Muito dinheiro em espécie.** Ao sair do Brasil com mais de 10 mil dólares em espécie (ou o equivalente em outra moeda), é preciso preencher a declaração eletrônica e-DBV, da Receita Federal. [12]"},{"t":"h","text":"Saúde e remédios"},{"t":"ul","items":["A vacina de febre amarela deve ser aplicada pelo menos 10 dias antes da viagem, e uma dose protege por toda a vida. [13]","Remédio líquido com prescrição pode ir na bagagem de mão acima de 100 ml, na quantidade para todo o voo, inclusive com escalas, e deve ser mostrado na inspeção. [14]"]},{"t":"p","text":"**Recomendação:** converse com seu médico, leve receita com o seu nome e os remédios de uso contínuo na bagagem de mão."},{"t":"ul","items":["☐ Orientação médica feita antes de viajar.","☐ Remédios na quantidade da viagem, com receita."]},{"t":"h","text":"Bagagem"},{"t":"ul","items":["**Mão.** A companhia deve permitir no mínimo 10 kg de bagagem de mão por passageiro, nas dimensões e na quantidade de peças definidas no contrato. Por segurança ou capacidade da aeronave, pode restringir peso e conteúdo (art. 14). [8, 11] As companhias normalmente permitem também um item pessoal, como bolsa ou mochila pequena, além dos 10 kg. Confira as medidas de cada companhia. [11]","**O que não vai na mão.** Não vão na bagagem de mão: armas (inclusive réplicas), lâminas acima de 6 cm, ferramentas, explosivos, líquidos inflamáveis, aerossóis (com exceção de até 4 de uso médico ou de higiene, de até 300 ml ou 300 g), isqueiro tipo maçarico e químicos tóxicos. A decisão final é da companhia ou do agente de segurança. [15, 16]","**Líquidos.** Em voo internacional, líquidos vão em frascos de até 100 ml, juntos numa embalagem plástica transparente de até 1 litro, uma por pessoa. Frasco maior não passa, mesmo parcialmente cheio. [14]","**Valores e extravio.** A ANAC orienta evitar despachar objetos de valor, como joias, dinheiro e eletrônicos, e levá-los no item pessoal. [11] Se a mala for extraviada, avise a companhia logo que notar. Ela pode ficar extraviada por no máximo 7 dias (voo doméstico) ou 21 dias (voo internacional) (art. 32). [8, 11]"]},{"t":"img","src":"/assets/blog/checklist-malas-coloridas.jpg","alt":"Fileiras de malas de rodinhas coloridas, em vermelho, verde, bege e azul, lado a lado","caption":"Mala de mão até 10 kg e mala despachada pesada em casa.","credit":"Foto: Jahra Tasfia Reza / Pexels","w":1000,"h":667},{"t":"ul","items":["☐ Mala de mão até 10 kg e mala despachada pesada em casa.","☐ Líquidos até 100 ml na embalagem transparente."]},{"t":"img","src":"/assets/blog/checklist-mala-aberta.jpg","alt":"Mala aberta vista de cima, com roupas, óculos de sol e divisória organizada, mãos ao redor","caption":"Líquidos até 100 ml vão juntos, na embalagem transparente.","credit":"Foto: SHVETS production / Pexels","w":1000,"h":667},{"t":"h","text":"Celular e internet"},{"t":"p","text":"O roaming internacional usa o seu número do Brasil fora do país, por acordo entre as operadoras, e pode ter cobrança extra conforme o pacote. Para ativar, use a opção Dados em roaming nas configurações do celular. [17]"},{"t":"p","text":"**Recomendação:** pergunte o preço do roaming à operadora e compare com chip local ou eSIM. Baixe mapas offline."},{"t":"ul","items":["☐ Internet do destino definida (roaming, chip ou eSIM).","☐ Mapas, reservas e cartão de embarque offline."]},{"t":"h","text":"Cópias dos documentos"},{"t":"p","text":"Em caso de furto, roubo ou extravio do passaporte, é preciso retirar outro. No exterior, procure a embaixada ou o consulado do Brasil, que emitem passaporte. [3, 18]"},{"t":"p","text":"**Recomendação:** guarde foto ou PDF do passaporte, da passagem, da apólice e das reservas na nuvem, e leve cópia impressa separada dos originais."},{"t":"ul","items":["☐ Cópia digital e impressa, longe dos originais."]},{"t":"h","text":"Contatos de emergência"},{"t":"p","text":"O Itamaraty trata como emergência consular o risco à vida, à segurança ou à dignidade (por exemplo, prisão, acidente grave, hospitalização e violência). Perda de passaporte, extravio de mala e voo perdido não são emergências. [19] O Itamaraty mantém a lista das repartições consulares do Brasil no exterior. [20]"},{"t":"p","text":"**Recomendação:** anote o telefone de um familiar, da seguradora, do banco (para bloquear o cartão), do hotel e do consulado do Brasil no destino."},{"t":"ul","items":["☐ Contatos anotados no papel e no celular."]},{"t":"h","text":"60, 30, 7 e 1 dia antes"},{"t":"p","text":"**Recomendação:** estes prazos são sugestões da Rota Certa. Os fatos estão nas seções acima."},{"t":"tip","items":["☐ Conferir a validade do passaporte e pedir novo, se precisar.","☐ Ver no site oficial do destino: visto, autorização e outras regras.","☐ Ver se destino e conexões exigem vacina (CIVP)."],"title":"60 dias"},{"t":"tip","items":["☐ Consulta médica, vacinas e receitas.","☐ Contratar o seguro viagem.","☐ Conferir a bagagem da tarifa e da companhia.","☐ Reservar hospedagem e anotar os endereços."],"title":"30 dias"},{"t":"img","src":"/assets/blog/checklist-dobrando-roupas.jpg","alt":"Mãos organizando roupas dobradas dentro de uma mala aberta","caption":"Faça as cópias dos documentos e separe o adaptador na semana da viagem.","credit":"Foto: Vlada Karpovich / Pexels","w":1000,"h":667},{"t":"tip","items":["☐ Conferir o nome do bilhete com o passaporte.","☐ Avisar o banco e definir a internet do destino.","☐ Fazer cópias dos documentos e separar o adaptador.","☐ Fazer a e-DBV, se levar mais de 10 mil dólares em espécie."],"title":"7 dias"},{"t":"tip","items":["☐ Fazer o check-in e baixar o cartão de embarque.","☐ Pesar a mala e separar líquidos de até 100 ml.","☐ Passaporte, receitas e valores na bolsa de mão.","☐ Carregar o celular e deixar os contatos à mão."],"title":"1 dia"},{"t":"img","src":"/assets/blog/checklist-mochila-de-croche.jpg","alt":"Mochila de crochê verde com detalhes em couro sobre cama branca, entre flores e um quadro, vista de cima","caption":"Passaporte, receitas e valores vão na bolsa de mão.","credit":"Foto: MADEINEGYPT.CA / Pexels","w":1000,"h":667},{"t":"pdf","href":"/guias/checklist-antes-de-viajar.pdf","note":"Leve o checklist com caixinhas no celular. Grátis, sem cadastro."},{"t":"h","text":"Não verificado"},{"t":"ul","items":["**Validade mínima do passaporte para entrar.** Cada país define. Não citamos número: veja no site oficial do destino.","**Tomadas e voltagem.** O guia mundial de tomadas da IEC saiu do ar. Confirme com o fabricante do adaptador, com o hotel ou com fonte do destino.","**Baterias de lítio e power bank.** Não achamos o limite oficial no texto consultado. Pergunte à companhia.","**Remédios controlados no exterior.** As regras variam por país. Confira com a embaixada ou o consulado do destino.","**Hora de abertura e fechamento do check-in.** A norma diz que é a companhia que define. Veja no seu bilhete.","**Avisar o banco, moeda e cartões.** São conselhos da Rota Certa, sem fonte oficial. Siga a orientação do seu banco.","**Roaming, chip local e eSIM.** Preços e condições são da operadora. A fonte oficial só explica o que é roaming.","**Cópias dos documentos e contatos.** Não achamos a orientação atual do Itamaraty sobre isso. Tratamos como conselho da Rota Certa.","**CIN em cada país.** A PF fala em RG emitido há menos de 10 anos. Para a CIN, confirme o país e a companhia.","**Regras de cada destino.** Este guia não cobre exigências de países específicos. Elas mudam."]},{"t":"tip","items":["[1] [gov.br, serviço Obter passaporte (Polícia Federal, última modificação 07/10/2026)](https://www.gov.br/pt-br/servicos/obter-passaporte-comum-para-brasileiro)","[2] [Polícia Federal, dúvidas sobre passaporte](https://www.gov.br/pf/pt-br/assuntos/passaporte/duvidas)","[3] [ANAC, documentos para embarque: adultos em voos internacionais (13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/documentos-para-embarque/adultos-brasileiros-voos-internacionais)","[4] [Governo Digital, A CIN pode ser utilizada no exterior? (16/07/2026)](https://www.gov.br/governodigital/pt-br/identidade/cin/perguntas-frequentes-sobre-a-cin/a-cin-pode-ser-utilizada)","[5] [ANAC, documentos para embarque: crianças e adolescentes em voos internacionais (13/04/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/documentos-para-embarque/criancas-e-adolescentes-brasileiros-de-0-a-17-anos-voos-internacionais)","[6] [Itamaraty, vistos para brasileiros (publicada em 14/06/2021)](https://www.gov.br/mre/pt-br/assuntos/portal-consular/vistos/vistos-para-brasileiros)","[7] [União Europeia, site oficial do ETIAS](https://travel-europe.europa.eu/en/etias)","[8] [ANAC, Resolução 400/2016, texto compilado (versão vigente em 22/10/2026), arts. 8, 13, 14, 16, 18, 19 e 32](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/resolucoes-2016/resolucao-no-400-13-12-2016)","[9] [gov.br, serviço Obter o Certificado Internacional de Vacinação e Profilaxia (CIVP)](https://www.gov.br/pt-br/servicos/obter-o-certificado-internacional-de-vacinacao-e-profilaxia)","[10] [Susep, seguro viagem (página modificada em 19/12/2022)](https://www.gov.br/susep/pt-br/assuntos/meu-futuro-seguro/seguros-previdencia-e-capitalizacao/seguros/seguro-viagem)","[11] [ANAC, página Bagagem (atualizada em 01/10/2026)](https://www.gov.br/anac/pt-br/assuntos/passageiros/bagagem)","[12] [gov.br, serviço Declarar bens para viagem internacional (e-DBV, Receita Federal)](https://www.gov.br/pt-br/servicos/declarar-bens-para-viagem-internacional-dbv)","[13] [Ministério da Saúde, febre amarela para viajantes](https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/f/febre-amarela/viajantes)","[14] [ANAC, transporte de líquidos em voos internacionais (24/03/2021)](https://www.gov.br/anac/pt-br/assuntos/passageiros/transporte-de-liquidos-em-voos-internacionais)","[15] [ANAC, itens que não podem ser levados na bagagem de mão (28/02/2024)](https://www.gov.br/anac/pt-br/assuntos/passageiros/itens-que-nao-podem-ser-levados-na-bagagem-de-mao)","[16] [ANAC, O que posso transportar (01/09/2025)](https://www.gov.br/anac/pt-br/assuntos/regulados/empresas-aereas/artigos-perigosos/o-que-posso-transportar)","[17] [Ministério das Comunicações, o que é roaming (25/08/2026)](https://www.gov.br/mcom/pt-br/noticias/noticias_alt/2026/agosto/entenda-o-que-e-o-roaming-e-como-funciona-essa-tecnologia)","[18] [Itamaraty, assistência consular](https://www.gov.br/mre/pt-br/assuntos/portal-consular/assistencia-consular)","[19] [Itamaraty, emergências no exterior (26/11/2025)](https://www.gov.br/mre/pt-br/assuntos/portal-consular/emergencias-no-exterior)","[20] [Itamaraty, repartições consulares do Brasil](https://www.gov.br/mre/pt-br/assuntos/portal-consular/reparticoes-consulares-do-brasil)","[21] [ANAC, Resolução 800/2026 (passageiro indisciplinado; alterou os arts. 5 e 18 da Res. 400)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-800)","[22] [ANAC, Resolução 813/2026 (altera a Res. 400; vale a partir de 26/10/2026)](https://www.anac.gov.br/assuntos/legislacao/legislacao-1/resolucoes/2026/resolucao-813)"],"title":"Fontes, conferidas em 22/10/2026"},{"t":"p","text":"**Versão da norma.** Resolução ANAC 400/2016, texto compilado no site da ANAC (última modificação em 26/08/2026, com as Resoluções 434/2017, 692/2022 e 800/2026 [21]), vigente em 22/10/2026. Os artigos citados são os dessa versão. A Resolução ANAC 813/2026 só vale a partir de 26/10/2026 e altera apenas os arts. 20, 25-A, 25-B, 26, 27, 27-A e 27-B da Resolução 400 (informação, responsabilidade e assistência em atrasos, cancelamentos e interrupções). Os demais artigos citados nestes guias não mudam. [22]"},{"t":"p","text":"Foto de capa: Vlada Karpovich / Pexels."},{"t":"whatsapp","message":"Oi, Rota Certa! Li o guia Checklist antes de viajar e quero cotar uma passagem."},{"t":"contato","title":"Fale com a gente no Direct do Instagram","text":"Tire dúvidas com a gente. Conte de onde você sai, para onde quer ir, o mês da viagem e quantas pessoas vão."}]', 11, datetime('now', '-4 minutes'));
